class BowlingGame:
    def __init__(self):
        self.rolls = []

    def roll(self, pins):
        if not 0 <= pins <= 10:
            raise Exception(f"Roll of {pins} pins is not allowed")
        self._validate(pins)
        self.rolls.append(pins)

    def score(self):
        if not self._is_game_over():
            raise Exception("Game is not complete")
        return self._calculate_score()

    def _validate(self, pins):
        if self._is_game_over():
            raise Exception("Cannot roll after game is over")
        frames, i = self._frame_bounds()
        if frames < 9:
            frame_total = sum(self.rolls[i:])
            if frame_total + pins > 10:
                raise Exception("Frame cannot score more than 10 points")
        else:
            tenth = self.rolls[i:]
            if len(tenth) == 2 and tenth[1] != 10 and tenth[1] + pins > 10:
                raise Exception("Frame cannot score more than 10 points")

    def _frame_bounds(self):
        rolls = self.rolls
        i = 0
        frames = 0
        while i < len(rolls) and frames < 9:
            if rolls[i] == 10:
                i += 1
            else:
                i += 2
            frames += 1
        return frames, i

    def _is_game_over(self):
        frames, i = self._frame_bounds()
        if frames < 10:
            return False
        tenth = self.rolls[i:]
        if not tenth:
            return False
        if tenth[0] == 10:
            return len(tenth) >= 3
        return len(tenth) >= 2

    def _calculate_score(self):
        rolls = self.rolls
        score = 0
        i = 0
        for _ in range(10):
            if rolls[i] == 10:
                score += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == 10:
                score += 10 + rolls[i + 2]
                i += 2
            else:
                score += rolls[i] + rolls[i + 1]
                i += 2
        return score

